import java.util.*;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;
        int v = sc.nextInt();
        int e = sc.nextInt();
        int src = sc.nextInt();
        int dst = sc.nextInt();
        if (src == dst) { System.out.println(0); return; }
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < v; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < e; i++) {
            int u = sc.nextInt();
            int to = sc.nextInt();
            adj.get(u).add(to);
            adj.get(to).add(u);
        }
        int[] dist = new int[v];
        Arrays.fill(dist, -1);
        dist[src] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.add(src);
        while (!q.isEmpty()) {
            int cur = q.poll();
            if (cur == dst) {
                System.out.println(dist[dst]);
                return;
            }
            for (int neighbor : adj.get(cur)) {
                if (dist[neighbor] == -1) {
                    dist[neighbor] = dist[cur] + 1;
                    q.add(neighbor);
                }
            }
        }
        System.out.println(-1);
    }
}

