#include <stdio.h>
#include <stdlib.h>

int main() {
    int v, e, src, dst;
    if (scanf("%d %d %d %d", &v, &e, &src, &dst) != 4) return 0;
    if (src == dst) { printf("0\n"); return 0; }

    int *head = malloc(v * sizeof(int));
    for (int i = 0; i < v; i++) head[i] = -1;
    int *to = malloc(2 * e * sizeof(int));
    int *next = malloc(2 * e * sizeof(int));
    int edge_cnt = 0;

    for (int i = 0; i < e; i++) {
        int u, v_node;
        scanf("%d %d", &u, &v_node);
        to[edge_cnt] = v_node; next[edge_cnt] = head[u]; head[u] = edge_cnt++;
        to[edge_cnt] = u; next[edge_cnt] = head[v_node]; head[v_node] = edge_cnt++;
    }

    int *dist = malloc(v * sizeof(int));
    for (int i = 0; i < v; i++) dist[i] = -1;
    dist[src] = 0;

    int *queue = malloc(v * sizeof(int));
    int q_head = 0, q_tail = 0;
    queue[q_tail++] = src;

    while (q_head < q_tail) {
        int cur = queue[q_head++];
        if (cur == dst) {
            printf("%d\n", dist[dst]);
            free(head); free(to); free(next); free(dist); free(queue);
            return 0;
        }
        for (int e_idx = head[cur]; e_idx != -1; e_idx = next[e_idx]) {
            int nxt = to[e_idx];
            if (dist[nxt] == -1) {
                dist[nxt] = dist[cur] + 1;
                queue[q_tail++] = nxt;
            }
        }
    }
    printf("-1\n");
    free(head); free(to); free(next); free(dist); free(queue);
    return 0;
}
